from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository


class CustomerInsightsService:
    def __init__(self, customers: InMemoryCustomerRepository, orders: InMemoryOrderRepository,
                 order_service: OrderService) -> None:
        self._customers = customers
        self._orders = orders
        self._order_service = order_service

    def get_lifetime_value(self, customer_id: str) -> dict:
        try:
            orders = self._order_service.list_for_customer(customer_id)
        except CustomerNotFound:
            raise

        active_orders = [o for o in orders if o.status != "cancelled"]
        lifetime_value_cents = sum(self._order_service.summarize(o).total_cents for o in active_orders)

        return {
            "order_count": len(active_orders),
            "lifetime_value_cents": lifetime_value_cents,
        }

    def get_top_customers(self, limit: int) -> list[dict]:
        customer_values = []
        for customer in self._customers.list_all():
            try:
                lifetime = self.get_lifetime_value(customer.customer_id)
                if lifetime["lifetime_value_cents"] > 0:
                    customer_values.append({
                        "customer_id": customer.customer_id,
                        "name": customer.name,
                        "lifetime_value_cents": lifetime["lifetime_value_cents"],
                    })
            except CustomerNotFound:
                pass

        customer_values.sort(key=lambda x: (-x["lifetime_value_cents"], x["customer_id"]))
        return customer_values[:limit]

