from typing import Any

from orders.application.customer_insights_service import CustomerInsightsService
from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, require_positive_int


class CustomerInsightsController:
    def __init__(self, order_service: OrderService, insights_service: CustomerInsightsService) -> None:
        self._order_service = order_service
        self._insights_service = insights_service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return Response(404, {"error": "customer not found"})

        order_entries = []
        for order in reversed(orders):
            summary = self._service.summarize(order)
            order_entries.append({
                "order_id": order.order_id,
                "status": order.status,
                "total_cents": summary.total_cents,
            })

        return Response(200, {
            "customer_id": customer_id,
            "orders": order_entries,
        })

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return Response(404, {"error": "customer not found"})

        active_orders = [o for o in orders if o.status != "cancelled"]
        lifetime_value_cents = sum(self._service.summarize(o).total_cents for o in active_orders)

        return Response(200, {
            "customer_id": customer_id,
            "order_count": len(active_orders),
            "lifetime_value_cents": lifetime_value_cents,
        })

    def handle_top_customers(self, limit: Any) -> Response:
        try:
            validated_limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)

        customer_values = []
        for customer in self._customers.list_all():
            orders = self._orders.list_for_customer(customer.customer_id)
            active_orders = [o for o in orders if o.status != "cancelled"]
            lifetime_value_cents = sum(self._service.summarize(o).total_cents for o in active_orders)

            if lifetime_value_cents > 0:
                customer_values.append({
                    "customer_id": customer.customer_id,
                    "name": customer.name,
                    "lifetime_value_cents": lifetime_value_cents,
                })

        customer_values.sort(key=lambda x: (-x["lifetime_value_cents"], x["customer_id"]))

        return Response(200, {
            "customers": customer_values[:validated_limit]
        })

